impl StepDependencies {
    /// Constructs an empty dependency graph (no edges) over ids. Fails
    /// with ExecutionError::DuplicateStepId if ids contains the same
    /// id more than once.
    pub fn new(ids: &[String]) -> Result<Self, ExecutionError> {
