pub async fn execute_pipeline_parallel(
    pipeline: &mut michi_core::pipeline::Pipeline,
    deps: &StepDependencies,
    runners: Vec<Box<dyn Step>>,
    breaker: std::sync::Arc<CircuitBreaker>,
    jitter_seed: f64,
    cancellation: &CancellationToken,
