    let mut seen_ids: HashSet<&str> = HashSet::new();
    let mut dup_ids: HashSet<&str> = HashSet::new();
    for step in &pipeline.steps {
        if !seen_ids.insert(step.id.as_str()) {
            dup_ids.insert(step.id.as_str());
