470	    /// Executes `step`, with behavior depending on [`CircuitBreaker::phase`].
471	    ///
472	    /// While `Open`, returns `Err(ExecutionError::CircuitOpen { retry_after_ms })`
473	    /// immediately without invoking `step` at all, where `retry_after_ms` is
474	    /// the time remaining until `open_duration` has elapsed since the
475	    /// breaker most recently opened.
476	    ///
477	    /// While `Closed`, retries retryable failures per `retry_config` with
478	    /// `next_retry_delay`'s backoff, threading `ExecutionError::Http`'s
479	    /// `retry_after` or `ExecutionError::CircuitOpen`'s `retry_after_ms`
480	    /// through when present -- including when either is wrapped inside
481	    /// `ExecutionError::StepFailed`'s `source`, which is unwrapped
482	    /// recursively. Returns immediately on success or
483	    /// on a non-retryable error, and returns the last error once
484	    /// `next_retry_delay` reports exhaustion. On success, resets the
485	    /// consecutive-failure counter; on a call-level failure (after retries
486	    /// are exhausted or the error is non-retryable), increments the counter
487	    /// once and opens the circuit at `failure_threshold`.
488	    ///
489	    /// While `HalfOpen`, runs `step` exactly once with no retries: success
490	    /// closes the circuit and resets the counter, and any failure reopens
491	    /// the circuit unconditionally, bypassing `failure_threshold`.
492	    pub async fn call(&self, step: &dyn Step, jitter_seed: f64) -> Result<(), ExecutionError> {
493	        let phase = self.phase();
494	        if phase == BreakerPhase::Open {
495	            let opened_at_ms = self.opened_at_ms.load(Ordering::SeqCst);
496	            let elapsed_ms = u64::try_from(self.epoch.elapsed().as_millis()).unwrap_or(u64::MAX);
497	            let open_duration_ms = u64::try_from(self.open_duration.as_millis()).unwrap_or(u64::MAX);
498	            let since_opened_ms = elapsed_ms.saturating_sub(opened_at_ms);
499	            let retry_after_ms = open_duration_ms.saturating_sub(since_opened_ms);
500	            return Err(ExecutionError::CircuitOpen { retry_after_ms });
501	        }
502	        if phase == BreakerPhase::HalfOpen {
503	            if self.half_open_claimed.compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst).is_err() {
504	                let open_duration_ms = u64::try_from(self.open_duration.as_millis()).unwrap_or(u64::MAX);
505	                return Err(ExecutionError::CircuitOpen { retry_after_ms: open_duration_ms });
506	            }
507	            let _gate_guard = HalfOpenGuard { claimed: &self.half_open_claimed };
508	            let attempt_result = match tokio::time::timeout(self.step_timeout, step.run(0)).await {
509	                Ok(result) => result,
510	                Err(_) => Err(ExecutionError::Timeout {
511	                    elapsed_ms: u64::try_from(self.step_timeout.as_millis()).unwrap_or(u64::MAX),
512	                }),
513	            };
514	            return match attempt_result {
515	                Ok(()) => {
516	                    self.phase.store(PHASE_CLOSED, Ordering::SeqCst);
517	                    self.record_success();
518	                    Ok(())
519	                }
520	                Err(err) => {
521	                    self.open_circuit();
522	                    Err(err)
523	                }
524	            };
525	        }
526	        let mut attempt = 0u32;
527	        loop {
